function fetchOrder(id) {
  return new Promise((resolve, reject) => {
    if (id === 404) {
      reject(new Error('order not found'));
    } else {
      resolve({ id, total: 42 });
    }
  });
}

async function getOrderSummary(id) {
  try {
    const order = await fetchOrder(id);
    return `order ${order.id}: $${order.total}`;
  } catch (err) {
    return `failed: ${err.message}`;
  } finally {
    console.log('lookup finished for', id);
  }
}

async function main() {
  console.log(await getOrderSummary(1));
  console.log(await getOrderSummary(404));
}

main();
